 static JsonNode? Outbound(JsonObject p)=>p["outbounds"]?.AsArray().FirstOrDefault(x=>x?["protocol"]?.ToString() is not ("freedom" or "blackhole" or "dns"));
 static string Country(JsonObject p){var text=p["remarks"]?.ToString()??"";var runes=text.EnumerateRunes().Select(r=>r.Value).ToArray();for(int i=0;i<runes.Length-1;i++)if(runes[i] is >=0x1F1E6 and <=0x1F1FF&&runes[i+1] is >=0x1F1E6 and <=0x1F1FF){var code=""+(char)('A'+runes[i]-0x1F1E6)+(char)('A'+runes[i+1]-0x1F1E6);return char.ConvertFromUtf32(runes[i])+char.ConvertFromUtf32(runes[i+1])+" "+code;}return "Unknown";}
