 void SampleTraffic(){if(xray==null){Metric("download","—");Metric("upload","—");return;}if(box==null){SampleSocksTraffic();return;}try{var nic=NetworkInterface.GetAllNetworkInterfaces().FirstOrDefault(n=>n.Name=="MelavoTUN");if(nic==null)return;var s=nic.GetIPStatistics();if(sampled){var seconds=Math.Max(.1,(DateTime.UtcNow-sampleAt).TotalSeconds);var rx=Math.Max(0,s.BytesReceived-lastRx);var tx=Math.Max(0,s.BytesSent-lastTx);totalRx+=rx;totalTx+=tx;Metric("download",Bytes((long)(rx/seconds))+"/s");Metric("upload",Bytes((long)(tx/seconds))+"/s");Metric("usage",Bytes(totalRx+totalTx));Metric("rx",Bytes(totalRx));Metric("tx",Bytes(totalTx));}lastRx=s.BytesReceived;lastTx=s.BytesSent;sampled=true;sampleAt=DateTime.UtcNow;}catch{}}
